use std::{fs,time::Instant};use wasmc_json_component::{Lib,wasmtime};use wasmtime::{Engine,Store};use wasmtime::component::{Component,Linker};
fn main(){let start=Instant::now();let e=Engine::default();let c=Component::new(&e,fs::read("publication/wasmc-json/component.wasm").unwrap()).unwrap();let mut s=Store::new(&e,());let lib=Lib::instantiate(&mut s,&c,&Linker::new(&e)).unwrap();let d=lib.wasmc_json_document();let n=5000;let input=format!("{}0{}","[".repeat(n),"]".repeat(n));let compact=d.call_compact_bytes(&mut s,input.as_bytes()).unwrap().unwrap();assert_eq!(compact,input);let result=d.call_select_bytes(&mut s,input.as_bytes(),&["/0".repeat(n)]).unwrap().unwrap();assert_eq!(result,vec![Some("0".to_string())]);assert_eq!(d.call_compact_bytes(&mut s,b"[true]").unwrap().unwrap(),"[true]");println!("{{\"accepted\":true,\"engine\":\"wasmtime-component\",\"nested_arrays\":{},\"pointer_segments\":{},\"same_instance_recovery\":true,\"elapsed_ms\":{}}}",n,n,start.elapsed().as_millis());}
